#pragma once
#include "common.hpp"
#include "objectives.hpp"
#include <functional>
#include <limits>
using namespace compose;
namespace rigid {
struct Scale { double l=1,v=1,e=1,p=1; };
struct Result {State s;bool ok=true;std::string reason;int iterations=0,evaluations=0,leaves=1,rejections=0;double residual=0;};
using Residual=std::function<V(const V&)>;
inline thread_local double solver_tolerance=3e-11;
inline thread_local double solver_fallback=2e-9;
inline V suffix(const Model&m){V s(m.count);double a=0;for(int i=m.count-1;i>=0;--i){a+=m.mass[i];s[i]=a;}return s;}
inline Mat angle_mass(const Model&m,const V&q){int n=m.count;V s=suffix(m);Mat a(n,n);for(int i=0;i<n;++i)for(int j=0;j<n;++j)a(i,j)=m.length[i]*m.length[j]*s[std::max(i,j)]*std::cos(q[i]-q[j]);return a;}
inline State cartesian(const Model&m,const V&z){int n=m.count;State s{V::Zero(2*n),V::Zero(2*n)};Eigen::Vector2d x=Eigen::Vector2d::Zero(),v=x;for(int j=0;j<n;++j){double q=z[j],w=z[n+j],l=m.length[j];x+=l*Eigen::Vector2d(std::sin(q),-std::cos(q));v+=l*w*Eigen::Vector2d(std::cos(q),std::sin(q));s.x.segment<2>(2*j)=x;s.v.segment<2>(2*j)=v;}return s;}
inline V angles(const Model&m,const State&s){V z(2*m.count);for(int j=0;j<m.count;++j){V e=edge(m,s.x,j),v=edge(m,s.v,j);z[j]=std::atan2(e[0],-e[1]);z[m.count+j]=(e[0]*v[1]-e[1]*v[0])/e.squaredNorm();}return z;}
inline V angle_ode(const Model&m,const V&z){int n=m.count;V q=z.head(n),w=z.tail(n),f(n),s=suffix(m);for(int i=0;i<n;++i){f[i]=s[i]*m.length[i]*(m.gravity[0]*std::cos(q[i])+m.gravity[1]*std::sin(q[i]));for(int j=0;j<n;++j)f[i]-=m.length[i]*m.length[j]*s[std::max(i,j)]*std::sin(q[i]-q[j])*w[j]*w[j];}V r(2*n);r<<w,angle_mass(m,q).ldlt().solve(f);return r;}
inline V rk4(const Model&m,V z,double h,int sub){double d=h/sub;for(int k=0;k<sub;++k){V a=angle_ode(m,z),b=angle_ode(m,z+.5*d*a),c=angle_ode(m,z+.5*d*b),e=angle_ode(m,z+d*c);z+=d*(a+2*b+2*c+e)/6;}return z;}
inline Scale scales(const Model&m,const State&s){Scale q;q.l=m.length.mean();q.e=std::max(1e-4,energy(m,s)-minimum_energy(m));q.v=std::sqrt(q.e/m.mass.mean());q.p=m.mass.mean()*q.l*q.v;return q;}
inline V encode(const State&s,const Scale&q){V y(2*s.x.size());y<<s.x/q.l,s.v/q.v;return y;}
inline State decode(const V&y,const Scale&q){int d=y.size()/2;return {q.l*y.head(d),q.v*y.tail(d)};}
inline V constraints(const Model&m,const V&x){V c(m.count);for(int j=0;j<m.count;++j)c[j]=.5*(edge(m,x,j).squaredNorm()-m.length[j]*m.length[j]);return c;}
inline Mat gradient(const Model&m,const V&x){Mat g=Mat::Zero(m.count,2*m.count);for(int j=0;j<m.count;++j){V e=edge(m,x,j);g.block(j,2*j,1,2)=e.transpose();if(j)g.block(j,2*j-2,1,2)=-e.transpose();}return g;}
inline V acceleration(const Model&m,const State&s){V inv=masses(m).cwiseInverse(),f=force(m,s.x),a=inv.cwiseProduct(f);Mat g=gradient(m,s.x);V b=g*a;for(int j=0;j<m.count;++j)b[j]+=edge(m,s.v,j).squaredNorm();V lam=(g*inv.asDiagonal()*g.transpose()).ldlt().solve(-b);return a+inv.cwiseProduct(g.transpose()*lam);}
inline V ode(const Model&m,const V&y,const Scale&q){State s=decode(y,q);V r(y.size());r<<s.v/q.l,acceleration(m,s)/q.v;return r;}
inline V invariants(const Model&m,const V&y,const Scale&q,double e,bool E,bool L=false,double targetL=0){int n=m.count;State s=decode(y,q);V r(2*n+(E?1:0)+(L?1:0));for(int j=0;j<n;++j){double l=m.length[j];V a=edge(m,s.x,j),b=edge(m,s.v,j);r[j]=.5*(a.squaredNorm()/(l*l)-1);r[n+j]=a.dot(b)/(l*q.v);}if(E)r[2*n]=(energy(m,s)-e)/q.e;if(L)r[r.size()-1]=(angular(m,s)-targetL)/(m.mass.sum()*q.l*q.v);return r;}
inline Mat inv_gradient(const Model&m,const V&y,const Scale&q,bool E,bool L=false){int n=m.count,d=2*n;State s=decode(y,q);Mat g=Mat::Zero(2*n+(E?1:0)+(L?1:0),2*d);for(int j=0;j<n;++j){double l=m.length[j];V a=edge(m,s.x,j),b=edge(m,s.v,j);for(int end=0;end<2;++end){int particle=j-end;if(particle<0)continue;double sign=end?-1:1;g.block(j,2*particle,1,2)=sign*q.l*a.transpose()/(l*l);g.block(n+j,2*particle,1,2)=sign*q.l*b.transpose()/(l*q.v);g.block(n+j,d+2*particle,1,2)=sign*a.transpose()/l;}}if(E){g.block(2*n,0,1,d)=(-q.l*force(m,s.x)/q.e).transpose();g.block(2*n,d,1,d)=(q.v*masses(m).cwiseProduct(s.v)/q.e).transpose();}if(L){for(int j=0;j<n;++j){double w=m.mass[j]/m.mass.sum();g(g.rows()-1,2*j)=w*s.v[2*j+1]/q.v;g(g.rows()-1,2*j+1)=-w*s.v[2*j]/q.v;g(g.rows()-1,d+2*j)=-w*s.x[2*j+1]/q.l;g(g.rows()-1,d+2*j+1)=w*s.x[2*j]/q.l;}}return g;}
inline V solve(V z,const Residual&f,Result&o,int limit=32,double tolerance=solver_tolerance){
 for(int it=0;it<limit;++it){V r=f(z);++o.evaluations;o.residual=r.norm();if(!r.allFinite()){o.ok=false;o.reason="nonfinite_residual";return z;}if(r.norm()<tolerance)return z;++o.iterations;Mat a(r.size(),z.size());for(int j=0;j<z.size();++j){double eps=2e-6*std::max(1.,std::abs(z[j]));V u=z,v=z;u[j]+=eps;v[j]-=eps;a.col(j)=(f(u)-f(v))/(2*eps);o.evaluations+=2;}V dz=a.completeOrthogonalDecomposition().solve(-r);if(!dz.allFinite()){o.ok=false;o.reason="nonfinite_increment";return z;}bool accept=false;double alpha=1;for(int k=0;k<16;++k){V p=z+alpha*dz,rr=f(p);++o.evaluations;if(rr.allFinite()&&rr.norm()<r.norm()){z=p;accept=true;break;}alpha*=.5;}if(!accept){o.ok=r.norm()<solver_fallback;o.reason=o.ok?"":"no_descent";return z;}}
 o.residual=f(z).norm();++o.evaluations;o.ok=o.residual<solver_fallback;if(!o.ok)o.reason="iteration_limit";return z;
}
inline Result rattle(const Model&m,const State&old,double h,const Scale&q){Result o;int n=m.count;V inv=masses(m).cwiseInverse(),a=inv.cwiseProduct(force(m,old.x));Mat g0=gradient(m,old.x),map=inv.asDiagonal()*g0.transpose();V free=old.x+h*old.v+.5*h*h*a;Residual f=[&](const V&z)->V{return constraints(m,free+map*z)/(q.l*q.l);};V lam=solve(V::Zero(n),f,o);o.s.x=free+map*lam;o.s.v=(o.s.x-old.x)/h+.5*h*a;Mat g=gradient(m,o.s.x);V mu=(g*inv.asDiagonal()*g.transpose()).ldlt().solve(-g*o.s.v);o.s.v+=inv.cwiseProduct(g.transpose()*mu);o.residual=std::max(o.residual,invariants(m,encode(o.s,q),q,0,false).norm());return o;}
inline Result dg(const Model&m,const State&old,double h,const Scale&q){Result o;int n=m.count,d=2*n;V inv=masses(m).cwiseInverse(),a=inv.cwiseProduct(force(m,old.x));V z=V::Zero(d+n);z.head(d)=(old.x+h*old.v+.5*h*h*acceleration(m,old))/q.l;Residual f=[&](const V&z)->V{V x=q.l*z.head(d);Mat gbar=.5*(gradient(m,old.x)+gradient(m,x));V r(d+n);r.head(d)=(x-old.x-h*old.v-.5*h*h*a)/q.l-inv.cwiseProduct(gbar.transpose()*z.tail(n));r.tail(n)=constraints(m,x)/(q.l*q.l);return r;};z=solve(z,f,o);o.s.x=q.l*z.head(d);o.s.v=2*(o.s.x-old.x)/h-old.v;return o;}
inline Result dg_full(const Model&m,const State&old,double h,const Scale&q){Result o;int n=m.count,d=2*n;V inv=masses(m).cwiseInverse(),a=inv.cwiseProduct(force(m,old.x)),ac=acceleration(m,old);V z=V::Zero(2*d+n);z.head(d)=(old.x+h*old.v+.5*h*h*ac)/q.l;z.segment(d,d)=(old.v+h*ac)/q.v;Residual f=[&](const V&z)->V{V x=q.l*z.head(d),v=q.v*z.segment(d,d);Mat gbar=.5*(gradient(m,old.x)+gradient(m,x));V r(2*d+n);r.head(d)=((x-old.x)/h-.5*(old.v+v))/q.v;r.segment(d,d)=(v-old.v-h*a)/q.v-inv.cwiseProduct(gbar.transpose()*z.tail(n));r.tail(n)=constraints(m,x)/(h*q.l*q.v);return r;};z=solve(z,f,o);o.s.x=q.l*z.head(d);o.s.v=q.v*z.segment(d,d);return o;}
inline Result projected(const Model&m,const State&old,double h,const Scale&q,const std::string&method){
 Result o;int d=2*m.count,Y=2*d;bool E=method.find("energy")!=std::string::npos,sym=method.find("sym_")==0,L=method.find("momentum")!=std::string::npos;int k=2*m.count+(E?1:0)+(L?1:0);V y0=encode(old,q),guess=y0+h*ode(m,y0,q);double target=energy(m,old),targetL=angular(m,old);Mat g0=inv_gradient(m,y0,q,E,L);
 if(sym){V z=V::Zero(Y+k);z.head(Y)=guess;Residual f=[&](const V&z)->V{V y=z.head(Y),mu=z.tail(k),a=y0+g0.transpose()*mu,b=y-inv_gradient(m,y,q,E,L).transpose()*mu;V r(Y+k);r.head(Y)=b-a-h*ode(m,.5*(a+b),q);r.tail(k)=invariants(m,y,q,target,E,L,targetL);return r;};z=solve(z,f,o);o.s=decode(z.head(Y),q);return o;}
 V ytarget;if(method.find("rattle_")==0){Result a=rattle(m,old,h,q);o.iterations+=a.iterations;o.evaluations+=a.evaluations;if(!a.ok)return a;ytarget=encode(a.s,q);}else {Residual f=[&](const V&y)->V{return y-y0-h*ode(m,.5*(y+y0),q);};ytarget=solve(guess,f,o);if(!o.ok){o.s=decode(ytarget,q);return o;}}
 if(method=="ode_midpoint"){o.s=decode(ytarget,q);return o;}V z=V::Zero(Y+k);z.head(Y)=ytarget;Residual f=[&](const V&z)->V{V y=z.head(Y);V r(Y+k);r.head(Y)=y-ytarget-inv_gradient(m,y,q,E,L).transpose()*z.tail(k);r.tail(k)=invariants(m,y,q,target,E,L,targetL);return r;};z=solve(z,f,o);o.s=decode(z.head(Y),q);return o;
}
inline V canonical(const Model&m,const State&s,const Scale&q){V a=angles(m,s),z(2*m.count);z.head(m.count)=a.head(m.count);z.tail(m.count)=angle_mass(m,a.head(m.count))*a.tail(m.count)/q.p;return z;}
inline State uncanonical(const Model&m,const V&z,const Scale&q){V a=z;a.tail(m.count)=angle_mass(m,z.head(m.count)).ldlt().solve(q.p*z.tail(m.count));return cartesian(m,a);}
inline double hamiltonian(const Model&m,const V&z,const Scale&q){return energy(m,uncanonical(m,z,q))/q.e;}
inline double hamiltonian_difference(const Model&m,const V&z0,const V&z1,const Scale&q){int n=m.count;V d=z1-z0,mid=.5*(z0+z1),w0=angle_mass(m,z0.head(n)).ldlt().solve(q.p*z0.tail(n)),w1=angle_mass(m,z1.head(n)).ldlt().solve(q.p*z1.tail(n)),s=suffix(m);Mat da(n,n);for(int i=0;i<n;++i)for(int j=0;j<n;++j)da(i,j)=-2*m.length[i]*m.length[j]*s[std::max(i,j)]*std::sin(mid[i]-mid[j])*std::sin(.5*(d[i]-d[j]));double delta=.5*(w1+w0).dot(q.p*d.tail(n))-.5*w1.dot(da*w0);for(int i=0;i<n;++i)delta-=2*s[i]*m.length[i]*std::sin(.5*d[i])*(m.gravity[0]*std::cos(mid[i])+m.gravity[1]*std::sin(mid[i]));return delta/q.e;}
inline V hamiltonian_gradient(const Model&m,const V&z,const Scale&q){int n=m.count;V p=q.p*z.tail(n),w=angle_mass(m,z.head(n)).ldlt().solve(p),s=suffix(m),g(2*n);for(int i=0;i<n;++i){g[i]=-s[i]*m.length[i]*(m.gravity[0]*std::cos(z[i])+m.gravity[1]*std::sin(z[i]));for(int j=0;j<n;++j)g[i]+=w[i]*w[j]*m.length[i]*m.length[j]*s[std::max(i,j)]*std::sin(z[i]-z[j]);g[i]/=q.e;}g.tail(n)=q.p*w/q.e;return g;}
inline Result canonical_step(const Model&m,const State&old,double h,const Scale&q,bool discrete,bool momentum=false,int quadrature=1,bool stable=false){Result o;int n=m.count;V z0=canonical(m,old,q);double e0=hamiltonian(m,z0,q);auto flow=[&](const V&g)->V{V f(2*n);f<<g.tail(n),-g.head(n);return (q.e/q.p)*f;};V guess=z0+h*flow(hamiltonian_gradient(m,z0,q));Residual f=[&](const V&z)->V{V delta=z-z0,g=hamiltonian_gradient(m,.5*(z+z0),q);if(quadrature==3){double a=std::sqrt(3./5)/2;g=(5.*hamiltonian_gradient(m,z0+(.5-a)*delta,q)+8.*g+5.*hamiltonian_gradient(m,z0+(.5+a)*delta,q))/18.;}V direction=delta;if(momentum){direction.head(n).array()-=direction.head(n).mean();if(stable)g.head(n).array()-=g.head(n).mean();}double den=stable?direction.squaredNorm():delta.dot(direction);double diff=stable?hamiltonian_difference(m,z0,z,q):hamiltonian(m,z,q)-e0;double work=stable&&momentum?g.dot(direction):g.dot(delta);if(discrete&&den>1e-22)g+=((diff-work)/den)*direction;return delta-h*flow(g);};V z=solve(guess,f,o);o.s=uncanonical(m,z,q);return o;}
inline Result raw(const Model&m,const State&s,double h,const Scale&q,const std::string&method){Result o;try{if(method=="rattle")o=rattle(m,s,h,q);else if(method=="cart_dg")o=dg(m,s,h,q);else if(method=="cart_dg_full")o=dg_full(m,s,h,q);else if(method.find("obj_")==0){std::string id=method.substr(4);objectives2::Variant variant;bool found=false;double reaction_weight=1;for(auto a:objectives2::variants())if(a.id==id){variant=a;found=true;}if(method.find("obj_reaction")==0){auto pos=method.find("_b",12);reaction_weight=std::stod(method.substr(12,pos-12));variant={method,"quarter","soft_midpoint","constant","verlet",std::stod(method.substr(pos+2)),true,false};found=true;}if(!found)throw std::runtime_error("unknown_objective");objectives2::Objective p(m,s,h,variant,q.e);Result target=rattle(m,s,h,q);if(!target.ok)return target;p.target=target.s;V afree=masses(m).cwiseInverse().cwiseProduct(force(m,s.x));p.aold=afree+reaction_weight*(acceleration(m,s)-afree);auto a=objectives2::solve(p,p.initial(variant.objective=="original"),48);o.s=a.state;o.ok=a.finite&&a.converged;o.reason=a.reason;o.iterations=a.iterations+target.iterations;o.evaluations=a.evaluations+target.evaluations;o.residual=std::max(a.balance,a.stationarity);}else if(method.find("canonical_")==0){Scale qq=q;if(method.find("p01")!=std::string::npos)qq.p*=.1;if(method.find("p10")!=std::string::npos)qq.p*=10;o=canonical_step(m,s,h,qq,method.find("midpoint")==std::string::npos,method.find("momentum")!=std::string::npos,method.find("avf")!=std::string::npos?3:1,method.find("stable")!=std::string::npos);}else o=projected(m,s,h,q,method);if(!finite(o.s)){o.ok=false;o.reason="nonfinite_state";}}catch(const std::exception&e){o.ok=false;o.reason=e.what();o.s=s;}return o;}
inline Result advance(const Model&m,const State&s,double h,const Scale&q,const std::string&method,int depth=0){std::size_t pos=method.find("_accuracy");if(pos==std::string::npos)return raw(m,s,h,q,method);std::string base=method.substr(0,pos);Result a=raw(m,s,h,q,base),b=raw(m,s,.5*h,q,base),c=b.ok?raw(m,b.s,.5*h,q,base):b;int it=a.iterations+b.iterations+(b.ok?c.iterations:0),ev=a.evaluations+b.evaluations+(b.ok?c.evaluations:0);double diff=a.ok&&b.ok&&c.ok?(encode(a.s,q)-encode(c.s,q)).norm():1e9;bool pass=a.ok&&b.ok&&c.ok&&diff<1e-4*std::abs(h);if(pass){c.iterations=it;c.evaluations=ev;c.leaves=2;return c;}if(depth>=12){c.ok=false;c.reason="accuracy_depth_limit";c.iterations=it;c.evaluations=ev;return c;}Result l=advance(m,s,.5*h,q,method,depth+1);if(!l.ok){l.iterations+=it;l.evaluations+=ev;++l.rejections;return l;}Result r=advance(m,l.s,.5*h,q,method,depth+1);r.iterations+=it+l.iterations;r.evaluations+=ev+l.evaluations;r.leaves+=l.leaves;r.rejections+=l.rejections+1;return r;}
inline Case make(std::string name,const V&angle,const V&omega,const V&mass,double g=9.81){Case c;c.name=name;c.model.name=name;c.model.count=angle.size();c.model.dim=2;c.model.rigid=true;c.model.mass=mass;c.model.length=V::Ones(angle.size());c.model.stiffness=V::Zero(angle.size());c.model.gravity=V::Zero(2);c.model.gravity[1]=-g;V z(2*angle.size());z<<angle,omega;c.initial=cartesian(c.model,z);return c;}
inline V vec(std::initializer_list<double>x){V v(x.size());int j=0;for(double a:x)v[j++]=a;return v;}
inline std::vector<Case> cases(){return {make("double_small",vec({.12,-.07}),vec({.1,-.05}),vec({1,1})),make("double_moderate",vec({.65,-.35}),vec({.5,-.2}),vec({1,1})),make("double_kick",vec({0,0}),vec({6.27,0}),vec({1,1})),make("double_fast",vec({.2,-.3}),vec({12,-8}),vec({1,1})),make("double_heavy_tip",vec({.45,-.25}),vec({.2,-.4}),vec({1,100})),make("double_light_tip",vec({.45,-.25}),vec({.2,-.4}),vec({1,.01})),make("triple_small",vec({.12,-.07,.04}),vec({.1,-.05,.02}),vec({1,1,1})),make("triple_moderate",vec({.45,-.3,.2}),vec({.3,-.2,.1}),vec({1,1,1})),make("triple_near_upright",vec({3.12,3.10,3.08}),vec({0,0,0}),vec({1,1,1})),make("triple_contrast",vec({.45,-.3,.2}),vec({.3,-.2,.1}),vec({1,20,.05})),make("double_free",vec({.3,-.2}),vec({4,-2}),vec({1,2}),0)};}
}
